cypher_query:
MATCH (e:Employee)-[:LOCATED_IN]->(r:Region)
WHERE EXISTS {
MATCH (e)-[rel]-()
WHERE type(rel) IN ['MANAGED_BY', 'HAS_SKILL', 'BELONGS_TO'] OR
EXISTS {
MATCH (e)-[:MANAGED_BY]-(c:Client)-[o:OPPORTUNITY]->(p:Product)
WHERE o.close_date >= '2025-01-01' AND o.close_date < '2026-01-01'
}
}
WITH e, r, count(*) AS activity_count
ORDER BY activity_count DESC
LIMIT 3
RETURN e.name AS employee_name, r.name AS region, activity_count
